#define _GNU_SOURCE

#include <errno.h>
#include <fcntl.h>
#include <linux/futex.h>
#include <linux/netlink.h>
#include <linux/vm_sockets.h>
#include <poll.h>
#include <signal.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <sys/syscall.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

struct call_result {
    long rc;
    int error;
};

static struct call_result socket_result(int domain, int type, int protocol) {
    errno = 0;
    int fd = socket(domain, type, protocol);
    struct call_result result = { .rc = fd, .error = fd < 0 ? errno : 0 };
    if (fd >= 0) {
        close(fd);
        result.rc = 0;
    }
    return result;
}

struct compat_observation {
    struct call_result socket_result;
    int connected;
    int connect_error;
    int skipped;
    int child_exit;
    int child_signal;
    int timed_out;
};

static struct call_result compat_vsock_socket(int *connected, int *connect_error) {
    struct call_result result = { .rc = -1, .error = ENOSYS };
    *connected = 0;
    *connect_error = 0;
#if defined(__x86_64__) && defined(MAP_32BIT)
    void *page = mmap(NULL, 4096, PROT_READ | PROT_WRITE,
                      MAP_PRIVATE | MAP_ANONYMOUS | MAP_32BIT, -1, 0);
    if (page == MAP_FAILED) {
        result.error = errno;
        return result;
    }

    uint32_t *args = page;
    if ((uintptr_t)args > UINT32_MAX) {
        result.error = EOVERFLOW;
        munmap(page, 4096);
        return result;
    }
    args[0] = AF_VSOCK;
    args[1] = SOCK_STREAM | SOCK_CLOEXEC | SOCK_NONBLOCK;
    args[2] = 0;

    register long rax __asm__("rax") = 102; /* i386 __NR_socketcall */
    register long rbx __asm__("rbx") = 1;   /* SYS_SOCKET */
    register long rcx __asm__("rcx") = (uintptr_t)args;
    __asm__ volatile("int $0x80"
                     : "+a"(rax)
                     : "b"(rbx), "c"(rcx)
                     : "memory", "cc", "r8", "r9", "r10", "r11");

    int32_t compat_ret = (int32_t)(uint32_t)rax;
    if (compat_ret < 0 && compat_ret >= -4095) {
        result.error = -compat_ret;
        munmap(page, 4096);
        return result;
    }

    int fd = compat_ret;
    result.rc = 0;
    result.error = 0;

    struct sockaddr_vm host;
    memset(&host, 0, sizeof(host));
    host.svm_family = AF_VSOCK;
    host.svm_cid = VMADDR_CID_HOST;
    host.svm_port = 3000;
    errno = 0;
    if (connect(fd, (struct sockaddr *)&host, sizeof(host)) == 0) {
        *connected = 1;
    } else if (errno == EINPROGRESS) {
        struct pollfd descriptor = { .fd = fd, .events = POLLOUT };
        int poll_rc = poll(&descriptor, 1, 1000);
        if (poll_rc > 0) {
            int socket_error = 0;
            socklen_t socket_error_size = sizeof(socket_error);
            if (getsockopt(fd, SOL_SOCKET, SO_ERROR, &socket_error,
                           &socket_error_size) == 0 && socket_error == 0) {
                *connected = 1;
            } else {
                *connect_error = socket_error != 0 ? socket_error : errno;
            }
        } else {
            *connect_error = poll_rc == 0 ? ETIMEDOUT : errno;
        }
    } else {
        *connect_error = errno;
    }
    close(fd);
    munmap(page, 4096);
#endif
    return result;
}

static struct compat_observation observe_compat_vsock(void) {
    struct compat_observation observation = {
        .socket_result = { .rc = -1, .error = ENOSYS },
        .connected = 0,
        .connect_error = 0,
        .skipped = 0,
        .child_exit = -1,
        .child_signal = 0,
        .timed_out = 0,
    };
    if (getenv("SKIP_COMPAT_VSOCK") != NULL) {
        observation.socket_result.error = ENOTSUP;
        observation.skipped = 1;
        return observation;
    }

    int report_pipe[2] = { -1, -1 };
    if (pipe2(report_pipe, O_CLOEXEC | O_NONBLOCK) != 0) {
        observation.socket_result.error = errno;
        return observation;
    }

    pid_t child = fork();
    if (child < 0) {
        observation.socket_result.error = errno;
        close(report_pipe[0]);
        close(report_pipe[1]);
        return observation;
    }
    if (child == 0) {
        close(report_pipe[0]);
        struct compat_observation child_report = observation;
        child_report.socket_result = compat_vsock_socket(
            &child_report.connected, &child_report.connect_error);
        (void)write(report_pipe[1], &child_report, sizeof(child_report));
        close(report_pipe[1]);
        _exit(0);
    }

    close(report_pipe[1]);
    struct pollfd descriptor = { .fd = report_pipe[0], .events = POLLIN | POLLHUP };
    int poll_rc = poll(&descriptor, 1, 2000);
    if (poll_rc > 0) {
        ssize_t received = read(report_pipe[0], &observation, sizeof(observation));
        if (received != (ssize_t)sizeof(observation)) {
            observation.socket_result.rc = -1;
            observation.socket_result.error = EIO;
        }
    } else if (poll_rc == 0) {
        observation.timed_out = 1;
        observation.socket_result.rc = -1;
        observation.socket_result.error = ETIMEDOUT;
        (void)kill(child, SIGKILL);
    } else {
        observation.socket_result.rc = -1;
        observation.socket_result.error = errno;
    }
    close(report_pipe[0]);

    int status = 0;
    if (waitpid(child, &status, 0) == child) {
        if (WIFEXITED(status)) observation.child_exit = WEXITSTATUS(status);
        if (WIFSIGNALED(status)) observation.child_signal = WTERMSIG(status);
    }
    return observation;
}

static struct call_result futex_call(uint32_t *address, int operation,
                                     uint32_t value, const void *timeout,
                                     uint32_t *second_address, uint32_t third_value) {
    errno = 0;
    long rc = syscall(SYS_futex, address, operation, value, timeout,
                      second_address, third_value);
    struct call_result result = { .rc = rc, .error = rc < 0 ? errno : 0 };
    return result;
}

int main(void) {
    struct call_result ipv6 = socket_result(AF_INET6, SOCK_DGRAM | SOCK_CLOEXEC, 0);
    struct call_result netlink = socket_result(AF_NETLINK, SOCK_RAW | SOCK_CLOEXEC, NETLINK_ROUTE);
    struct call_result unix_socket = socket_result(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0);
    struct call_result algorithm_socket = socket_result(AF_ALG, SOCK_SEQPACKET | SOCK_CLOEXEC, 0);
    struct call_result direct_vsock = socket_result(AF_VSOCK, SOCK_STREAM | SOCK_CLOEXEC, 0);
    struct compat_observation compat_vsock = observe_compat_vsock();

    uint32_t pi_word = 0;
    struct call_result futex_lock = futex_call(&pi_word,
        FUTEX_LOCK_PI | FUTEX_PRIVATE_FLAG, 0, NULL, NULL, 0);
    struct call_result futex_unlock = { .rc = -999, .error = 0 };
    if (futex_lock.rc == 0) {
        futex_unlock = futex_call(&pi_word,
            FUTEX_UNLOCK_PI | FUTEX_PRIVATE_FLAG, 0, NULL, NULL, 0);
    }
    /*
     * Exercise both PI-requeue opcodes without creating a waiter or entering
     * rt_mutex_start_proxy_lock().  Distinct aligned words and zero waiters
     * make CMP_REQUEUE_PI return before any proxy-lock rollback.  The
     * deliberately mismatched WAIT_REQUEUE_PI value cannot sleep; the expired
     * absolute timeout is a second fail-closed bound if kernel behavior ever
     * changes.
     */
    uint32_t requeue_source = 0;
    uint32_t requeue_target = 0;
    struct call_result futex_requeue_pi = futex_call(&requeue_source,
        FUTEX_CMP_REQUEUE_PI | FUTEX_PRIVATE_FLAG, 1,
        (const void *)(uintptr_t)1, &requeue_target, 0);
    uint32_t wait_requeue_source = 1;
    uint32_t wait_requeue_target = 0;
    const struct timespec expired = { .tv_sec = 0, .tv_nsec = 0 };
    struct call_result futex_wait_requeue_pi = futex_call(
        &wait_requeue_source, FUTEX_WAIT_REQUEUE_PI | FUTEX_PRIVATE_FLAG, 0,
        &expired, &wait_requeue_target, 0);

    int sock = socket(AF_INET6, SOCK_DGRAM | SOCK_CLOEXEC, 0);
    int pipefd[2] = { -1, -1 };
    int pipe_rc = pipe2(pipefd, O_CLOEXEC | O_NONBLOCK);

    struct call_result splice_result = { .rc = -999, .error = 0 };
    if (sock >= 0 && pipe_rc == 0) {
        errno = 0;
        splice_result.rc = splice(pipefd[0], NULL, sock, NULL, 0, SPLICE_F_NONBLOCK);
        splice_result.error = splice_result.rc < 0 ? errno : 0;
    }

    struct call_result sendmsg_result = { .rc = -999, .error = 0 };
    if (sock >= 0) {
        struct msghdr message;
        memset(&message, 0, sizeof(message));
        errno = 0;
        sendmsg_result.rc = sendmsg(sock, &message, MSG_DONTWAIT);
        sendmsg_result.error = sendmsg_result.rc < 0 ? errno : 0;
    }

    if (pipefd[0] >= 0) close(pipefd[0]);
    if (pipefd[1] >= 0) close(pipefd[1]);
    if (sock >= 0) close(sock);

    printf("{\"uid\":%ld,\"gid\":%ld,"
           "\"proc_if_inet6_readable\":%s,"
           "\"socket_af_inet6_udp\":{\"rc\":%ld,\"errno\":%d},"
           "\"socket_netlink_route\":{\"rc\":%ld,\"errno\":%d},"
           "\"socket_af_unix_stream\":{\"rc\":%ld,\"errno\":%d},"
           "\"socket_af_alg_seqpacket\":{\"rc\":%ld,\"errno\":%d},"
           "\"socket_af_vsock_direct\":{\"rc\":%ld,\"errno\":%d},"
           "\"socket_af_vsock_i386_socketcall\":{\"skipped\":%s,"
           "\"rc\":%ld,\"errno\":%d,\"cid2_port3000_connected\":%s,"
           "\"connect_errno\":%d,\"child_exit\":%d,\"child_signal\":%d,"
           "\"timed_out\":%s},"
           "\"futex_lock_pi_private\":{\"rc\":%ld,\"errno\":%d},"
           "\"futex_unlock_pi_private\":{\"rc\":%ld,\"errno\":%d},"
           "\"futex_cmp_requeue_pi_distinct_no_waiters\":{\"rc\":%ld,\"errno\":%d},"
           "\"futex_wait_requeue_pi_mismatched_expired\":{\"rc\":%ld,\"errno\":%d},"
           "\"splice_zero_length\":{\"rc\":%ld,\"errno\":%d},"
           "\"sendmsg_empty_no_more\":{\"rc\":%ld,\"errno\":%d}}\n",
           (long)getuid(), (long)getgid(),
           access("/proc/net/if_inet6", R_OK) == 0 ? "true" : "false",
           ipv6.rc, ipv6.error,
           netlink.rc, netlink.error,
           unix_socket.rc, unix_socket.error,
           algorithm_socket.rc, algorithm_socket.error,
           direct_vsock.rc, direct_vsock.error,
           compat_vsock.skipped ? "true" : "false",
           compat_vsock.socket_result.rc, compat_vsock.socket_result.error,
           compat_vsock.connected ? "true" : "false", compat_vsock.connect_error,
           compat_vsock.child_exit, compat_vsock.child_signal,
           compat_vsock.timed_out ? "true" : "false",
           futex_lock.rc, futex_lock.error,
           futex_unlock.rc, futex_unlock.error,
           futex_requeue_pi.rc, futex_requeue_pi.error,
           futex_wait_requeue_pi.rc, futex_wait_requeue_pi.error,
           splice_result.rc, splice_result.error,
           sendmsg_result.rc, sendmsg_result.error);
    return 0;
}

assets.io.c:
#define _GNU_SOURCE

#include <errno.h>
#include <limits.h>
#include <linux/io_uring.h>
#include <poll.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/syscall.h>
#include <time.h>
#include <unistd.h>

#if !defined(SYS_io_uring_setup) || !defined(SYS_io_uring_enter)
#error "the target libc headers do not expose the io_uring syscalls"
#endif

/*
 * This is deliberately a capability gate, not an exploitation primitive.
 * It creates a one-entry ring, submits exactly one IORING_OP_NOP, observes at
 * most one CQE, and tears the ring down. It contains no socket or connect path
 * and never calls io_uring_register().
 */
#define COMPLETION_TIMEOUT_MS 1500
#define NOP_USER_DATA UINT64_C(0x4e4f505f47415445) /* "NOP_GATE" */

struct probe_result {
    const char *stage;
    long setup_rc;
    int setup_errno;
    unsigned sq_entries;
    unsigned cq_entries;
    unsigned features;
    long enter_rc;
    int enter_errno;
    int poll_rc;
    int poll_errno;
    bool poll_attempted;
    bool cqe_observed;
    int cqe_res;
    unsigned cqe_flags;
    bool user_data_match;
    unsigned setup_calls;
    unsigned enter_calls;
    unsigned sqes_initialized;
    unsigned sqes_published;
    unsigned sqes_submitted;
    unsigned cqes_consumed;
    bool passed;
};

static int64_t monotonic_ms(void) {
    struct timespec now;

    if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
        return -1;
    }
    return (int64_t)now.tv_sec * 1000 + now.tv_nsec / 1000000;
}

static bool region_size(uint32_t offset, uint32_t entries, size_t item_size,
                        size_t *result) {
    if ((size_t)entries > (SIZE_MAX - (size_t)offset) / item_size) {
        return false;
    }
    *result = (size_t)offset + (size_t)entries * item_size;
    return *result != 0;
}

static bool cqe_available(void *cq_ring, const struct io_uring_params *params) {
    uint32_t *head = (uint32_t *)((uint8_t *)cq_ring + params->cq_off.head);
    uint32_t *tail = (uint32_t *)((uint8_t *)cq_ring + params->cq_off.tail);

    return __atomic_load_n(tail, __ATOMIC_ACQUIRE) !=
           __atomic_load_n(head, __ATOMIC_RELAXED);
}

static int wait_for_cqe(int ring_fd, void *cq_ring,
                        const struct io_uring_params *params,
                        struct probe_result *result) {
    int64_t start = monotonic_ms();
    int64_t deadline;

    if (cqe_available(cq_ring, params)) {
        return 1;
    }
    if (start < 0 || start > INT64_MAX - COMPLETION_TIMEOUT_MS) {
        result->stage = "clock_gettime";
        return -1;
    }
    deadline = start + COMPLETION_TIMEOUT_MS;

    for (;;) {
        int64_t now = monotonic_ms();
        int timeout;
        struct pollfd descriptor;
        int rc;

        if (now < 0) {
            result->stage = "clock_gettime";
            return -1;
        }
        if (now >= deadline) {
            result->stage = "completion_timeout";
            return 0;
        }
        timeout = (int)(deadline - now);
        descriptor.fd = ring_fd;
        descriptor.events = POLLIN;
        descriptor.revents = 0;

        errno = 0;
        result->poll_attempted = true;
        rc = poll(&descriptor, 1, timeout);
        result->poll_rc = rc;
        result->poll_errno = rc < 0 ? errno : 0;
        if (rc < 0 && errno == EINTR) {
            continue;
        }
        if (rc < 0) {
            result->stage = "poll";
            return -1;
        }
        if (rc == 0) {
            result->stage = "completion_timeout";
            return 0;
        }
        if (cqe_available(cq_ring, params)) {
            return 1;
        }
        if (descriptor.revents & (POLLERR | POLLHUP | POLLNVAL)) {
            result->stage = "poll_revents";
            return -1;
        }
    }
}

static void print_result(const struct probe_result *result, int64_t elapsed_ms) {
    printf("{\"probe\":\"io_uring_nop_gate\","
           "\"stage\":\"%s\",\"passed\":%s,"
           "\"requested_entries\":1,"
           "\"setup\":{\"rc\":%ld,\"errno\":%d,"
           "\"sq_entries\":%u,\"cq_entries\":%u,\"features\":%u},"
           "\"enter\":{\"rc\":%ld,\"errno\":%d,"
           "\"to_submit\":1,\"min_complete\":0,\"flags\":0},"
           "\"wait\":{\"method\":\"poll\",\"timeout_ms\":%d,"
           "\"attempted\":%s,\"rc\":%d,\"errno\":%d},"
           "\"completion\":{\"observed\":%s,\"res\":%d,"
           "\"flags\":%u,\"user_data_match\":%s},"
           "\"safety\":{\"io_uring_setup_calls\":%u,"
           "\"io_uring_enter_calls\":%u,\"sqes_initialized\":%u,"
           "\"sqes_published\":%u,\"sqes_submitted\":%u,"
           "\"cqes_consumed\":%u,\"cqes_consumed_max\":1,"
           "\"opcode\":\"IORING_OP_NOP\","
           "\"io_uring_register_called\":false,"
           "\"socket_opcode_submitted\":false,"
           "\"network_operations_attempted\":0},"
           "\"elapsed_ms\":%lld}\n",
           result->stage, result->passed ? "true" : "false",
           result->setup_rc, result->setup_errno, result->sq_entries,
           result->cq_entries, result->features, result->enter_rc,
           result->enter_errno, COMPLETION_TIMEOUT_MS,
           result->poll_attempted ? "true" : "false", result->poll_rc,
           result->poll_errno, result->cqe_observed ? "true" : "false",
           result->cqe_res, result->cqe_flags,
           result->user_data_match ? "true" : "false",
           result->setup_calls, result->enter_calls,
           result->sqes_initialized, result->sqes_published,
           result->sqes_submitted, result->cqes_consumed,
           (long long)elapsed_ms);
}

int main(void) {
    struct probe_result result = {
        .stage = "io_uring_setup",
        .setup_rc = -1,
        .setup_errno = 0,
        .sq_entries = 0,
        .cq_entries = 0,
        .features = 0,
        .enter_rc = -1,
        .enter_errno = 0,
        .poll_rc = -1,
        .poll_errno = 0,
        .poll_attempted = false,
        .cqe_observed = false,
        .cqe_res = 0,
        .cqe_flags = 0,
        .user_data_match = false,
        .setup_calls = 0,
        .enter_calls = 0,
        .sqes_initialized = 0,
        .sqes_published = 0,
        .sqes_submitted = 0,
        .cqes_consumed = 0,
        .passed = false,
    };
    struct io_uring_params params;
    int ring_fd = -1;
    void *sq_ring = MAP_FAILED;
    void *cq_ring = MAP_FAILED;
    struct io_uring_sqe *sqes = MAP_FAILED;
    size_t sq_ring_size = 0;
    size_t cq_ring_size = 0;
    size_t shared_ring_size = 0;
    size_t sqes_size = 0;
    bool shared_ring = false;
    int exit_status = 1;
    int64_t started_ms = monotonic_ms();
    int64_t finished_ms;

    memset(&params, 0, sizeof(params));
    errno = 0;
    result.setup_calls = 1;
    ring_fd = (int)syscall(SYS_io_uring_setup, 1U, &params);
    result.setup_rc = ring_fd;
    result.setup_errno = ring_fd < 0 ? errno : 0;
    if (ring_fd < 0) {
        goto cleanup;
    }
    result.sq_entries = params.sq_entries;
    result.cq_entries = params.cq_entries;
    result.features = params.features;
    if (params.sq_entries == 0 || params.cq_entries == 0 ||
        !region_size(params.sq_off.array, params.sq_entries,
                     sizeof(uint32_t), &sq_ring_size) ||
        !region_size(params.cq_off.cqes, params.cq_entries,
                     sizeof(struct io_uring_cqe), &cq_ring_size) ||
        !region_size(0, params.sq_entries, sizeof(struct io_uring_sqe),
                     &sqes_size)) {
        result.stage = "invalid_ring_layout";
        goto cleanup;
    }

    if (params.features & IORING_FEAT_SINGLE_MMAP) {
        shared_ring = true;
        shared_ring_size = sq_ring_size > cq_ring_size ?
                           sq_ring_size : cq_ring_size;
        sq_ring = mmap(NULL, shared_ring_size, PROT_READ | PROT_WRITE,
                       MAP_SHARED, ring_fd, IORING_OFF_SQ_RING);
        if (sq_ring == MAP_FAILED) {
            result.stage = "mmap_shared_ring";
            goto cleanup;
        }
        cq_ring = sq_ring;
    } else {
        sq_ring = mmap(NULL, sq_ring_size, PROT_READ | PROT_WRITE,
                       MAP_SHARED, ring_fd, IORING_OFF_SQ_RING);
        if (sq_ring == MAP_FAILED) {
            result.stage = "mmap_sq_ring";
            goto cleanup;
        }
        cq_ring = mmap(NULL, cq_ring_size, PROT_READ | PROT_WRITE,
                       MAP_SHARED, ring_fd, IORING_OFF_CQ_RING);
        if (cq_ring == MAP_FAILED) {
            result.stage = "mmap_cq_ring";
            goto cleanup;
        }
    }

    sqes = mmap(NULL, sqes_size, PROT_READ | PROT_WRITE, MAP_SHARED,
                ring_fd, IORING_OFF_SQES);
    if (sqes == MAP_FAILED) {
        result.stage = "mmap_sqes";
        goto cleanup;
    }

    {
        uint32_t *sq_head =
            (uint32_t *)((uint8_t *)sq_ring + params.sq_off.head);
        uint32_t *sq_tail =
            (uint32_t *)((uint8_t *)sq_ring + params.sq_off.tail);
        uint32_t *sq_mask =
            (uint32_t *)((uint8_t *)sq_ring + params.sq_off.ring_mask);
        uint32_t *sq_array =
            (uint32_t *)((uint8_t *)sq_ring + params.sq_off.array);
        uint32_t head = __atomic_load_n(sq_head, __ATOMIC_ACQUIRE);
        uint32_t tail = __atomic_load_n(sq_tail, __ATOMIC_RELAXED);
        uint32_t mask = __atomic_load_n(sq_mask, __ATOMIC_RELAXED);
        uint32_t slot;

        if (tail - head >= params.sq_entries || mask >= params.sq_entries) {
            result.stage = "invalid_sq_state";
            goto cleanup;
        }
        slot = tail & mask;
        memset(&sqes[slot], 0, sizeof(sqes[slot]));
        sqes[slot].opcode = IORING_OP_NOP;
        sqes[slot].user_data = NOP_USER_DATA;
        result.sqes_initialized = 1;
        sq_array[slot] = slot;
        __atomic_store_n(sq_tail, tail + 1, __ATOMIC_RELEASE);
        result.sqes_published = 1;
    }

    result.stage = "io_uring_enter";
    errno = 0;
    result.enter_calls = 1;
    result.enter_rc = syscall(SYS_io_uring_enter, ring_fd, 1U, 0U, 0U,
                              NULL, 0U);
    result.enter_errno = result.enter_rc < 0 ? errno : 0;
    if (result.enter_rc > 0) {
        result.sqes_submitted = (unsigned)result.enter_rc;
    }
    if (result.enter_rc != 1) {
        goto cleanup;
    }

    result.stage = "completion_wait";
    if (wait_for_cqe(ring_fd, cq_ring, &params, &result) != 1) {
        goto cleanup;
    }

    {
        uint32_t *cq_head =
            (uint32_t *)((uint8_t *)cq_ring + params.cq_off.head);
        uint32_t *cq_mask =
            (uint32_t *)((uint8_t *)cq_ring + params.cq_off.ring_mask);
        struct io_uring_cqe *cqes =
            (struct io_uring_cqe *)((uint8_t *)cq_ring + params.cq_off.cqes);
        uint32_t head = __atomic_load_n(cq_head, __ATOMIC_RELAXED);
        uint32_t mask = __atomic_load_n(cq_mask, __ATOMIC_RELAXED);
        struct io_uring_cqe *cqe;

        if (mask >= params.cq_entries) {
            result.stage = "invalid_cq_state";
            goto cleanup;
        }
        cqe = &cqes[head & mask];
        result.cqe_observed = true;
        result.cqe_res = cqe->res;
        result.cqe_flags = cqe->flags;
        result.user_data_match = cqe->user_data == NOP_USER_DATA;
        __atomic_store_n(cq_head, head + 1, __ATOMIC_RELEASE);
        result.cqes_consumed = 1;
    }

    if (!result.user_data_match) {
        result.stage = "unexpected_completion";
        goto cleanup;
    }
    if (result.cqe_res != 0) {
        result.stage = "nop_completion_error";
        goto cleanup;
    }

    result.stage = "complete";
    result.passed = true;
    exit_status = 0;

cleanup:
    if (sqes != MAP_FAILED) {
        (void)munmap(sqes, sqes_size);
    }
    if (shared_ring) {
        if (sq_ring != MAP_FAILED) {
            (void)munmap(sq_ring, shared_ring_size);
        }
    } else {
        if (cq_ring != MAP_FAILED) {
            (void)munmap(cq_ring, cq_ring_size);
        }
        if (sq_ring != MAP_FAILED) {
            (void)munmap(sq_ring, sq_ring_size);
        }
    }
    if (ring_fd >= 0) {
        (void)close(ring_fd);
    }

    finished_ms = monotonic_ms();
    print_result(&result,
                 started_ms >= 0 && finished_ms >= started_ms ?
                 finished_ms - started_ms : -1);
    return exit_status;
}
